import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        K = int(next(iterator))
    except StopIteration:
        return

    true_graph = defaultdict(list)
    floor_graph = defaultdict(list)

    for _ in range(K):
        x1 = int(next(iterator))
        y1 = int(next(iterator))
        z1 = int(next(iterator))
        x2 = int(next(iterator))
        y2 = int(next(iterator))
        z2 = int(next(iterator))

        u3 = (x1, y1, z1)
        v3 = (x2, y2, z2)

        u2 = (x1, y1)
        v2 = (x2, y2)

        true_graph[u3].append(v3)
        true_graph[v3].append(u3)

        floor_graph[u2].append(v2)
        floor_graph[v2].append(u2)

    def has_cycle(graph):
        visited = {}
        nodes = list(graph.keys())

        for start_node in nodes:
            if start_node in visited:
                continue

            stack = [(start_node, None)]
            path_nodes = set()

            while stack:
                node, parent = stack.pop()

                if node in path_nodes:
                    return True

                if node in visited:
                    continue

                path_nodes.add(node)
                visited[node] = True

                neighbors = graph.get(node, [])
                for neighbor in neighbors:
                    if neighbor != parent:
                        stack.append((neighbor, node))

            for n in path_nodes:
                if n in visited:
                    pass

        return False

    has_true_cycle = has_cycle(true_graph)
    has_floor_cycle = has_cycle(floor_graph)

    if has_true_cycle:
        print("True closed chains")
    else:
        print("No true closed chains")

    if has_floor_cycle:
        print("Floor closed chains")
    else:
        print("No floor closed chains")

if __name__ == "__main__":
    main()
